mapper.select:
SELECT 
FROM opc_crm_customer

    deleted = 0
    AND owner_id = #{ownerId}
    AND level = #{level}
    AND source = #{source}
    AND FIND_IN_SET(#{tag}, tags)

        AND (name LIKE CONCAT('%', #{keyword}, '%') OR phone LIKE CONCAT('%', #{keyword}, '%'))


ORDER BY create_time DESC
